// 301 : ancien article espagnol isole -> nouvel article bilingue
add_action( 'template_redirect', function() {
	$uri = isset( $_SERVER['REQUEST_URI'] ) ? wp_parse_url( $_SERVER['REQUEST_URI'], PHP_URL_PATH ) : '';
	if ( preg_match( '#^/(es_es/)?corte-de-luz-estacion-portatil-panel-solar/?$#', $uri ) ) {
		wp_redirect( 'https://www.solandvolt.com/es_es/coupure-courant-station-portable-panneau-solaire/', 301 );
		exit;
	}
}, 1 );


// 301 : pas de version espagnole de la page anglaise
add_action( 'template_redirect', function() {
	$uri = isset( $_SERVER['REQUEST_URI'] ) ? wp_parse_url( $_SERVER['REQUEST_URI'], PHP_URL_PATH ) : '';
	if ( preg_match( '#^/es_es/en(/|$)#', $uri ) ) {
		wp_redirect( 'https://www.solandvolt.com' . preg_replace( '#^/es_es#', '', $uri ), 301 );
		exit;
	}
}, 1 );

// Pas de hreflang TranslatePress sur la page anglaise (le snippet en emet deja de corrects)
add_filter( 'trp-exclude-hreflang', function( $exclude, $original_url ) {
	$path = wp_parse_url( $original_url, PHP_URL_PATH );
	if ( preg_match( '#^/en(/|$)#', $path ) ) return true;
	return $exclude;
}, 10, 2 );

